WITH parsed AS (SELECT id, plan, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE plan IN ('pro', 'basic', 'enterprise')) SELECT id, avg_tier_price, LEAD(avg_tier_price) OVER w_ordered AS next_avg_tier_price, LAG(lowest_price) OVER w_ordered AS prev_lowest_price, LEAD(lowest_price) OVER w_ordered AS next_lowest_price, ROW_NUMBER() OVER w_ordered AS event_seq FROM parsed WINDOW w_ordered AS (PARTITION BY plan ORDER BY lowest_price, id)
